*** Add File: script.js
+const form = document.querySelector("#support-form");
+const statusMessage = document.querySelector("#form-status");
+
+const fields = {
+  fullName: {
+    input: document.querySelector("#full-name"),
+    error: document.querySelector("#full-name-error"),
+    validate(value) {
+      return value.trim() ? "" : "Enter your full name.";
+    },
+  },
+  email: {
+    input: document.querySelector("#email"),
+    error: document.querySelector("#email-error"),
+    validate(value) {
+      const trimmedValue = value.trim();
+
+      if (!trimmedValue) {
+        return "Enter your email address.";
+      }
+
+      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)) {
+        return "Enter an email address in the format name@example.com.";
+      }
+
+      return "";
+    },
+  },
+  phone: {
+    input: document.querySelector("#phone"),
+    error: document.querySelector("#phone-error"),
+    validate(value) {
+      const trimmedValue = value.trim();
+
+      if (!trimmedValue) {
+        return "";
+      }
+
+      if (!/^\+?[0-9\s().-]{7,20}$/.test(trimmedValue)) {
+        return "Enter a phone number using 7 to 20 digits, spaces, dashes, or parentheses.";
+      }
+
+      return "";
+    },
+  },
+};
+
+function setFieldError(input, errorElement, message) {
+  errorElement.textContent = message;
+
+  if (message) {
+    input.setAttribute("aria-invalid", "true");
+  } else {
+    input.removeAttribute("aria-invalid");
+  }
+}
+
+function validateField(field) {
+  const message = field.validate(field.input.value);
+  setFieldError(field.input, field.error, message);
+  return !message;
+}
+
+function validateForm() {
+  let firstInvalidInput = null;
+
+  Object.values(fields).forEach((field) => {
+    const isValid = validateField(field);
+
+    if (!isValid && !firstInvalidInput) {
+      firstInvalidInput = field.input;
+    }
+  });
+
+  return firstInvalidInput;
+}
+
+Object.values(fields).forEach((field) => {
+  field.input.addEventListener("input", () => {
+    validateField(field);
+    statusMessage.textContent = "";
+  });
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+  statusMessage.textContent = "";
+
+  const firstInvalidInput = validateForm();
+
+  if (firstInvalidInput) {
+    firstInvalidInput.focus();
+    return;
+  }
+
+  form.reset();
+  Object.values(fields).forEach((field) => {
+    setFieldError(field.input, field.error, "");
+  });
+  statusMessage.textContent = "Thanks. Your support request is ready to send.";
+});
*** End Patch
