+<!DOCTYPE html>
+<html lang="en">
+  <head>
+    <meta charset="UTF-8" />
+    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
+    <title>Support Contact Form</title>
+    <link rel="stylesheet" href="styles.css" />
+    <script src="script.js" defer></script>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+
+    <main id="main-content" class="page-shell">
+      <section class="contact-card" aria-labelledby="contact-heading">
+        <div class="eyebrow">Support request</div>
+        <h1 id="contact-heading">How can we help?</h1>
+        <p class="intro">
+          Send our support team your contact details and we will follow up with
+          you as soon as possible.
+        </p>
+
+        <form class="support-form" id="support-form" novalidate>
+          <div class="form-field">
+            <label for="full-name">Full name <span aria-hidden="true">*</span></label>
+            <input
+              id="full-name"
+              name="fullName"
+              type="text"
+              autocomplete="name"
+              required
+              aria-describedby="full-name-error"
+            />
+            <p class="error-message" id="full-name-error"></p>
+          </div>
+
+          <div class="form-field">
+            <label for="email">Email address <span aria-hidden="true">*</span></label>
+            <input
+              id="email"
+              name="email"
+              type="email"
+              autocomplete="email"
+              required
+              aria-describedby="email-error"
+            />
+            <p class="error-message" id="email-error"></p>
+          </div>
+
+          <div class="form-field">
+            <label for="phone">Phone number <span class="optional">(optional)</span></label>
+            <input
+              id="phone"
+              name="phone"
+              type="tel"
+              autocomplete="tel"
+              inputmode="tel"
+              aria-describedby="phone-help phone-error"
+            />
+            <p class="helper-text" id="phone-help">
+              Use digits, spaces, dashes, or parentheses, such as (555) 123-4567.
+            </p>
+            <p class="error-message" id="phone-error"></p>
+          </div>
+
+          <button type="submit">Submit support request</button>
+          <p class="form-status" id="form-status" aria-live="polite"></p>
+        </form>
+      </section>
+    </main>
+  </body>
+</html>
+



